export function findCountryByCode(code: string): WorldCountryData | undefined {
  if (!code) return undefined;
  const upper = code.toUpperCase().trim();
  return WORLD_COUNTRIES.find((c) => c.code === upper);
}

export function searchCountries(query: string): WorldCountryData[] {
  if (!query || !query.trim()) return WORLD_COUNTRIES;
  const q = query.toLowerCase().trim();
  return WORLD_COUNTRIES.filter(
    (c) =>
      c.code.toLowerCase().includes(q) ||
      c.nameAr.toLowerCase().includes(q) ||
      c.nameEn.toLowerCase().includes(q) ||
      c.currencyCode.toLowerCase().includes(q)
  );
}
